SELECT 
FROM ai_agent_dialogue_session
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
  AND deleted = 0
LIMIT 1

SELECT 
FROM ai_agent_dialogue_session
WHERE deleted = 0
  AND (
      user_id = #{userId}
      OR binding_id IN (
          SELECT id FROM ai_agent_channel_binding
          WHERE owner_user_id = #{userId}
            AND deleted = 0
      )
  )

ORDER BY last_active_at DESC, id DESC
LIMIT #{limit}

